$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$route = Decode ""

$slotMapPath = Join-Path $root "app\api\market\requests\[id]\split-fallback\slot-map\route.ts"
$targetDir = Join-Path $root "app\api\market\requests\[id]\split-fallback\confirm"
$targetPath = Join-Path $targetDir "route.ts"
$reviewPath = Join-Path $root "app\assistant\market\[id]\split-plan\page.tsx"

foreach ($required in @($slotMapPath, $reviewPath)) {
    if (-not (Test-Path -LiteralPath $required)) {
        throw "13.19c : prerequisite introuvable : $required"
    }
}

$slotMap = [System.IO.File]::ReadAllText($slotMapPath)
$review = [System.IO.File]::ReadAllText($reviewPath)

if (-not $slotMap.Contains("KLYX_MULTI_PROVIDER_EXACT_SLOT_MAP_13_16")) {
    throw "13.19c : API slot-map 13.16 introuvable."
}

if (-not $review.Contains("KLYX_SPLIT_PLAN_CONFIRMATION_WIRING_13_18")) {
    Write-Host "ATTENTION : marker UI 13.18 absent, mais restauration API possible."
}

New-Item -ItemType Directory -Force -Path $targetDir | Out-Null

if (Test-Path -LiteralPath $targetPath) {
    $existing = [System.IO.File]::ReadAllText($targetPath)

    if ($existing.Contains("KLYX_SPLIT_PLAN_CONFIRMATION_API_13_18")) {
        Write-Host "API confirmation deja presente."
        exit 0
    }

    $timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

    Copy-Item -LiteralPath $targetPath -Destination ($targetPath + ".bak-13-19c-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($targetPath, $route, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.19c APPLIQUE"
Write-Host "======================================"
Write-Host "API confirmation 13.18 : RESTAUREE"
Write-Host "GET validation preuve : RESTAURE"
Write-Host "POST confirmation plan : RESTAURE"
Write-Host "Revalidation slot-map 13.16 : ACTIVE"
Write-Host "SHA-256 : ACTIVE"
Write-Host "Booking : NON CREE PAR CE FIX"
Write-Host "Paiement : NON"
Write-Host "Migration : AUCUNE"
Write-Host "======================================"
